// --- Update function ---
const slider = document.getElementById('reactionProgress');
const captionEl = document.getElementById('stageCaption');

function updateScene(t) {
  // Positions
  const nuX = lerp(-3.0, -1.1, t);
  const xX = lerp(1.1, 3.0, t);
  nuMesh.position.set(nuX, 0, 0);
  xMesh.position.set(xX, 0, 0);
  cMesh.position.set(0, 0, 0);

  // Substituent positions
  const a = 0.333 * (2 * t - 1);
  const r = Math.sqrt(Math.max(0, 1 - a * a));
  const bondLen = 1.1;
  for (let i = 0; i < 3; i++) {
    const angle = (i * 120) * Math.PI / 180;
    const px = a * bondLen;
    const py = r * bondLen * Math.cos(angle);
    const pz = r * bondLen * Math.sin(angle);
    subMeshes[i].position.set(px, py, pz);
    // Update C-substituent bond
    const posAttr = subBondGeos[i].attributes.position;
    posAttr.setXYZ(0, 0, 0, 0);
    posAttr.setXYZ(1, px, py, pz);
    posAttr.needsUpdate = true;
  }

  // Nu-C bond
  const nuCPosAttr = nuCBondGeo.attributes.position;
  nuCPosAttr.setXYZ(0, nuX, 0, 0);
  nuCPosAttr.setXYZ(1, 0, 0, 0);
  nuCPosAttr.needsUpdate = true;
  nuCBondGeo.computeBoundingSphere();
  nuCBond.computeLineDistances();
  const nuCBondOrder = Math.max(0, Math.min(1, (t - 0.2) / 0.6)); // 0 before 0.2, 1 after 0.8
  nuCBondMat.opacity = t < 0.15 ? 0 : (nuCBondOrder < 0.9 ? 0.7 : 1);
  nuCBondMat.dashSize = nuCBondOrder < 0.9 ? 0.08 : 10; // solid when fully formed
  nuCBondMat.gapSize = nuCBondOrder < 0.9 ? 0.05 : 0;
  nuCBond.visible = t > 0.1;

  // C-X bond
  const cXPosAttr = cXBondGeo.attributes.position;
  cXPosAttr.setXYZ(0, 0, 0, 0);
  cXPosAttr.setXYZ(1, xX, 0, 0);
  cXPosAttr.needsUpdate = true;
  cXBondGeo.computeBoundingSphere();
  cXBond.computeLineDistances();
  const cXBondOrder = Math.max(0, Math.min(1, 1 - (t - 0.2) / 0.6)); // 1 before 0.2, 0 after 0.8
  cXBondMat.opacity = t > 0.85 ? 0 : (cXBondOrder < 0.9 ? 0.7 : 1);
  cXBondMat.dashSize = cXBondOrder < 0.9 ? 0.08 : 10;
  cXBondMat.gapSize = cXBondOrder < 0.9 ? 0.05 : 0;
  cXBond.visible = t < 0.9;

  // ESP colors
  const qNu = lerp(-1, -0.2, t);
  const qX = lerp(-0.2, -1, t);
  const qC = 0;
  nuMat.color.copy(chargeToColor(qNu));
  xMat.color.copy(chargeToColor(qX));
  cMat.color.copy(chargeToColor(qC));

  // Halo colors and sizes
  const haloScale = 1 + 0.8 * Math.sin(Math.PI * t); // peaks at t=0.5
  haloNu.position.copy(nuMesh.position);
  haloNu.scale.setScalar(haloScale);
  haloNuMat.color.copy(chargeToColor(qNu));
  haloNuMat.opacity = 0.12 + 0.08 * Math.sin(Math.PI * t);

  haloC.position.set(0, 0, 0);
  haloC.scale.setScalar(haloScale * 0.9);
  haloCMat.opacity = 0.1 + 0.1 * Math.sin(Math.PI * t);

  haloX.position.copy(xMesh.position);
  haloX.scale.setScalar(haloScale);
  haloXMat.color.copy(chargeToColor(qX));
  haloXMat.opacity = 0.12 + 0.08 * Math.sin(Math.PI * t);

  // Labels
  lblNu.pos.set(nuX, 0.6, 0);
  lblX.pos.set(xX, 0.6, 0);
  lblDeltaNu.pos.set(nuX, 0.95, 0);
  lblDeltaX.pos.set(xX, 0.95, 0);

  // Show δ− only near transition state
  const showDelta = Math.abs(t - 0.5) < 0.25;
  lblDeltaNu.div.style.display = showDelta ? '' : 'none';
  lblDeltaX.div.style.display = showDelta ? '' : 'none';

  // Caption
  if (t < 0.33) captionEl.textContent = 'Tetrahedral';
  else if (t <= 0.67) captionEl.textContent = 'Planar (transition state)';
  else captionEl.textContent = 'Tetrahedral';
}

slider.addEventListener('input', () => {
  updateScene(parseFloat(slider.value));
});

// --- Demo step tweening ---
let tweenAnim = null;
function goToStep(targetT, duration = 1200) {
  if (tweenAnim) cancelAnimationFrame(tweenAnim);
  const startT = parseFloat(slider.value);
  const startTime = performance.now();
  function tick(now) {
    const elapsed = now - startTime;
    const progress = Math.min(1, elapsed / duration);
    const eased = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
    const currentT = startT + (targetT - startT) * eased;
    slider.value = currentT;
    updateScene(currentT);
    if (progress < 1) {
      tweenAnim = requestAnimationFrame(tick);
    } else {
      tweenAnim = null;
    }
  }
  tweenAnim = requestAnimationFrame(tick);
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(0.5));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(1));

// --- Initial update ---
updateScene(0);

// --- Camera ---
setCameraView({
  projection: 'perspective',
  azimuthDeg: 55,
  elevationDeg: 16,
  rollDeg: 0,
  heightFraction: 0.62
});
