const MAGENTA = 0xd6219c;
const MAGENTA_CSS = '#d6219c';

// Charge-to-color mapping
function chargeToColor(q) {
  // q=-1 → red #d23b3b, q=-0.5 → yellow #e8d44f, q=0 → green #7fbf6f, q>0 → blue #5a7fcf
  const red = new THREE.Color(0xd23b3b);
  const yellow = new THREE.Color(0xe8d44f);
  const green = new THREE.Color(0x7fbf6f);
  const blue = new THREE.Color(0x5a7fcf);
  const c = new THREE.Color();
  if (q <= -0.5) {
    const f = (q + 1) / 0.5; // 0 at q=-1, 1 at q=-0.5
    c.lerpColors(red, yellow, Math.max(0, Math.min(1, f)));
  } else if (q <= 0) {
    const f = (q + 0.5) / 0.5; // 0 at q=-0.5, 1 at q=0
    c.lerpColors(yellow, green, Math.max(0, Math.min(1, f)));
  } else {
    const f = Math.min(1, q / 0.5);
    c.lerpColors(green, blue, Math.max(0, Math.min(1, f)));
  }
  return c;
}

function lerp(a, b, t) { return a + (b - a) * t; }

