let tweenAnim = null;
function goToStep(targetT, duration = 1200) {
  if (tweenAnim) cancelAnimationFrame(tweenAnim);
  const startT = parseFloat(slider.value);
  const startTime = performance.now();
  function tick(now) {
    const elapsed = now - startTime;
    const progress = Math.min(1, elapsed / duration);
    const eased = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;
    const currentT = startT + (targetT - startT) * eased;
    slider.value = currentT;
    updateScene(currentT);
    if (progress < 1) {
      tweenAnim = requestAnimationFrame(tick);
    } else {
      tweenAnim = null;
    }
  }
  tweenAnim = requestAnimationFrame(tick);
}

