// @FIGURE_CODE_BEGIN
// === ELEMENT SPEC ===
// C atom        -> SphereGeometry(0.30) MeshStandardMaterial FIXED grey #808080 (never recolored)
// Nu atom       -> SphereGeometry(0.40) MeshStandardMaterial FIXED dark red #b02a3a
// X atom        -> SphereGeometry(0.40) MeshStandardMaterial FIXED red-orange #c23b2e
// 3 substituents-> SphereGeometry(0.20) MeshStandardMaterial FIXED light grey #c8c8c8
// Nu-C bond     -> Line dashed->solid as it forms
// C-X bond      -> Line solid->dashed as it breaks
// 3 C-sub bonds -> Line solid grey
// ESP envelope  -> single vertex-colored metaball isosurface (red->green->blue gradient), translucent
// Labels        -> Nu, C, X, delta- via addLabel
// Scheme panel  -> HTML rows in #ui, active stage highlighted

const MAGENTA_CSS = '#d6219c';

// --- Lights ---
const keyLight = new THREE.DirectionalLight(0xffffff, 1.25);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.5);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);
scene.add(new THREE.AmbientLight(0xffffff, 0.35));

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp01(v) { return Math.max(0, Math.min(1, v)); }

// ESP scalar -> color gradient: blue(e=+0.45) -> green(e=-0.05) -> red(e=-0.95)
const _cBlue = new THREE.Color(0x3f6fd0);
const _cGreen = new THREE.Color(0x7fbf6f);
const _cYellow = new THREE.Color(0xe8d44f);
const _cRed = new THREE.Color(0xd23b3b);
const _tmpC = new THREE.Color();
function espColor(e, out) {
  // e negative = electron rich = red ; e positive = electron poor = blue
  if (e <= -0.5) {
    const f = clamp01((-0.95 - e) / 0.45); // 0 at -0.95 .. 1 deeper
    out.lerpColors(_cRed, _cRed, 0); // stay red
    out.copy(_cRed);
  } else if (e <= -0.05) {
    const f = clamp01((e + 0.5) / 0.45); // 0 at -0.5 (red) .. 1 at -0.05 (green)
    out.lerpColors(_cRed, _cGreen, f);
  } else if (e <= 0.2) {
    const f = clamp01((e + 0.05) / 0.25);
    out.lerpColors(_cGreen, _cBlue, f);
  } else {
    out.copy(_cBlue);
  }
  return out;
}

// --- Atom meshes (FIXED ball-and-stick colors) ---
const cMat = new THREE.MeshStandardMaterial({ color: 0x808080, roughness: 0.4, metalness: 0.1 });
const cMesh = new THREE.Mesh(new THREE.SphereGeometry(0.30, 32, 32), cMat);
scene.add(cMesh);

const nuMat = new THREE.MeshStandardMaterial({ color: 0xb02a3a, roughness: 0.35, metalness: 0.05 });
const nuMesh = new THREE.Mesh(new THREE.SphereGeometry(0.40, 32, 32), nuMat);
scene.add(nuMesh);

const xMat = new THREE.MeshStandardMaterial({ color: 0xc23b2e, roughness: 0.35, metalness: 0.05 });
const xMesh = new THREE.Mesh(new THREE.SphereGeometry(0.40, 32, 32), xMat);
scene.add(xMesh);

const subMeshes = [];
for (let i = 0; i < 3; i++) {
  const m = new THREE.MeshStandardMaterial({ color: 0xc8c8c8, roughness: 0.5, metalness: 0.05 });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.20, 24, 24), m);
  scene.add(mesh);
  subMeshes.push(mesh);
}

// --- Bonds ---
function makeBond(dashed) {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute([0,0,0,0,0,0], 3));
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color: 0x666666, dashSize: 0.09, gapSize: 0.06, transparent: true, opacity: 1 })
    : new THREE.LineBasicMaterial({ color: 0x555555 });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  return { geo, mat, line };
}
const nuCBond = makeBond(true);
const cXBond = makeBond(true);
const subBonds = [makeBond(false), makeBond(false), makeBond(false)];

function setBond(b, ax,ay,az, bx,by,bz) {
  const p = b.geo.attributes.position;
  p.setXYZ(0, ax, ay, az);
  p.setXYZ(1, bx, by, bz);
  p.needsUpdate = true;
  b.geo.computeBoundingSphere();
  if (b.line.computeLineDistances) b.line.computeLineDistances();
}

// --- ESP metaball envelope (vertex-colored gradient isosurface) ---
const ENV_SEG = 44;
const envGeo = new THREE.SphereGeometry(1, ENV_SEG, ENV_SEG);
const envPosAttr = envGeo.attributes.position;
const envColors = new Float32BufferAttribute(new Float32Array(envPosAttr.count * 3), 3);
envGeo.setAttribute('color', envColors);
const envMat = new THREE.MeshStandardMaterial({
  vertexColors: true, transparent: true, opacity: 0.62,
  roughness: 0.32, metalness: 0.05, side: THREE.DoubleSide, depthWrite: false
});
const envMesh = new THREE.Mesh(envGeo, envMat);
scene.add(envMesh);

// metaball field sources: {center:Vector3, strength, charge}
const _srcs = [];
const _centroid = new THREE.Vector3();
const _dirV = new THREE.Vector3();
const _pV = new THREE.Vector3();
const _dV = new THREE.Vector3();
const ISO = 1.0;

function buildEnvelope() {
  // sources from current atom positions
  _srcs.length = 0;
  _srcs.push({ c: nuMesh.position, s: 1.25, q: _qNu });
  _srcs.push({ c: xMesh.position,  s: 1.25, q: _qX });
  _srcs.push({ c: cMesh.position,  s: 0.95, q: _qC });
  for (const sm of subMeshes) _srcs.push({ c: sm.position, s: 0.42, q: 0.0 });

  _centroid.set(0,0,0);
  _centroid.add(nuMesh.position).add(xMesh.position).add(cMesh.position).multiplyScalar(1/3);

  const R_MIN = 0.18, R_MAX = 3.2, STEPS = 46;
  for (let i = 0; i < envPosAttr.count; i++) {
    _dirV.set(envPosAttr.getX(i), envPosAttr.getY(i), envPosAttr.getZ(i)).normalize();
    // march outward from centroid along dir, find surface where field crosses ISO
    let rSurf = R_MIN;
    let prevField = fieldAt(_centroid.x + _dirV.x*R_MIN, _centroid.y + _dirV.y*R_MIN, _centroid.z + _dirV.z*R_MIN);
    for (let s = 1; s <= STEPS; s++) {
      const r = R_MIN + (R_MAX - R_MIN) * (s / STEPS);
      const px = _centroid.x + _dirV.x*r, py = _centroid.y + _dirV.y*r, pz = _centroid.z + _dirV.z*r;
      const f = fieldAt(px, py, pz);
      if (prevField >= ISO && f < ISO) {
        // linear interp crossing
        const t = (prevField - ISO) / (prevField - f + 1e-9);
        rSurf = (r - (R_MAX-R_MIN)/STEPS) + t * ((R_MAX-R_MIN)/STEPS);
        break;
      }
      prevField = f;
      rSurf = r;
    }
    if (prevField >= ISO) rSurf = R_MAX * 0.5; // still inside -> clamp modest
    const px = _centroid.x + _dirV.x*rSurf;
    const py = _centroid.y + _dirV.y*rSurf;
    const pz = _centroid.z + _dirV.z*rSurf;
    envPosAttr.setXYZ(i, px, py, pz);
    // ESP value at surface point
    const e = espAt(px, py, pz);
    espColor(e, _tmpC);
    envColors.setXYZ(i, _tmpC.r, _tmpC.g, _tmpC.b);
  }
  envPosAttr.needsUpdate = true;
  envColors.needsUpdate = true;
  envGeo.computeVertexNormals();
  envGeo.computeBoundingSphere();
}

function fieldAt(px, py, pz) {
  let f = 0;
  for (const src of _srcs) {
    const dx = px - src.c.x, dy = py - src.c.y, dz = pz - src.c.z;
    f += src.s / (dx*dx + dy*dy + dz*dz + 0.05);
  }
  return f;
}
function espAt(px, py, pz) {
  let e = 0;
  for (const src of _srcs) {
    const dx = px - src.c.x, dy = py - src.c.y, dz = pz - src.c.z;
    e += src.q * src.s / (dx*dx + dy*dy + dz*dz + 0.08);
  }
  return e;
}

// --- Labels ---
const lblNu = addLabel('Nu', new THREE.Vector3(-3, 0.6, 0), { color: MAGENTA_CSS, bold: true, fontSize: '14px' });
const lblC = addLabel('C', new THREE.Vector3(0, 0.5, 0), { color: MAGENTA_CSS, bold: true, fontSize: '14px' });
const lblX = addLabel('X', new THREE.Vector3(1.1, 0.6, 0), { color: MAGENTA_CSS, bold: true, fontSize: '14px' });
const lblDeltaNu = addLabel('δ<sup>−</sup>', new THREE.Vector3(-3, 0.95, 0), { color: MAGENTA_CSS, fontSize: '12px' });
const lblDeltaX = addLabel('δ<sup>−</sup>', new THREE.Vector3(1.1, 0.95, 0), { color: MAGENTA_CSS, fontSize: '12px' });

// --- Interactivity ---
registerInteractive(nuMesh, {
  title: 'Nucleophile (Nu)',
  body: 'The nucleophile attacks from the backside (180° from the leaving group). It is electron-rich (red in the ESP envelope); its negative charge transfers to the leaving group as the reaction proceeds.',
  tooltip: 'Nucleophile — electron-rich (red ESP)'
});
registerInteractive(xMesh, {
  title: 'Leaving group (X)',
  body: 'The leaving group departs with the bonding electron pair. It is electron-rich (red ESP) at every stage and becomes a free anion X⁻ in the products.',
  tooltip: 'Leaving group — electron-rich (red ESP)'
});
registerInteractive(cMesh, {
  title: 'Electrophilic carbon (C)',
  body: 'The carbon is electron-poor (green/blue ESP) and undergoes Walden inversion: its three substituents flip like an umbrella through a planar transition state. The grey ball keeps the standard ball-and-stick palette; the ESP color lives in the surrounding envelope.',
  tooltip: 'Electrophilic carbon — electron-poor (green/blue ESP)'
});

// --- State charges (drive ESP only, NOT ball colors) ---
let _qNu = -1, _qX = -0.7, _qC = 0.3;

// --- Update ---
const slider = document.getElementById('reactionProgress');
