  // C-X bond (breaks)
  const cXOrder = clamp01(1 - (t - 0.2) / 0.6);
  setBond(cXBond, 0,0,0, xX,0,0);
  cXBond.line.visible = t < 0.92;
  if (cXOrder < 0.9) { cXBond.mat.dashSize = 0.09; cXBond.mat.gapSize = 0.06; cXBond.mat.opacity = 0.75; }
  else { cXBond.mat.dashSize = 10; cXBond.mat.gapSize = 0; cXBond.mat.opacity = 1; }

  // ESP charges (balls stay fixed color)
  _qNu = lerp(-1.0, -0.15, t);
  _qX  = lerp(-0.7, -1.0, t);
  _qC  = lerp(0.35, 0.1, t);

  // rebuild gradient envelope
  buildEnvelope();

  // labels
  lblNu.pos.set(nuX, 0.62, 0);
  lblX.pos.set(xX, 0.62, 0);
  lblDeltaNu.pos.set(nuX, 0.98, 0);
  lblDeltaX.pos.set(xX, 0.98, 0);
  const showDelta = Math.abs(t - 0.5) < 0.28;
  lblDeltaNu.div.style.display = showDelta ? '' : 'none';
  lblDeltaX.div.style.display = showDelta ? '' : 'none';

  // caption + scheme highlight
  if (t < 0.33) { captionEl.textContent = 'Tetrahedral'; highlightRow(0); }
  else if (t <= 0.67) { captionEl.textContent = 'Planar (transition state)'; highlightRow(1); }
  else { captionEl.textContent = 'Tetrahedral'; highlightRow(2); }
}

