  _srcs.push({ c: xMesh.position,  s: 1.25, q: _qX });
  _srcs.push({ c: cMesh.position,  s: 0.95, q: _qC });
  for (const sm of subMeshes) _srcs.push({ c: sm.position, s: 0.42, q: 0.0 });

  _centroid.set(0,0,0);
  _centroid.add(nuMesh.position).add(xMesh.position).add(cMesh.position).multiplyScalar(1/3);

  const R_MIN = 0.18, R_MAX = 3.2, STEPS = 46;
  for (let i = 0; i < envPosAttr.count; i++) {
    _dirV.set(envPosAttr.getX(i), envPosAttr.getY(i), envPosAttr.getZ(i)).normalize();
    // march outward from centroid along dir, find surface where field crosses ISO
    let rSurf = R_MIN;
    let prevField = fieldAt(_centroid.x + _dirV.x*R_MIN, _centroid.y + _dirV.y*R_MIN, _centroid.z + _dirV.z*R_MIN);
    for (let s = 1; s <= STEPS; s++) {
      const r = R_MIN + (R_MAX - R_MIN) * (s / STEPS);
      const px = _centroid.x + _dirV.x*r, py = _centroid.y + _dirV.y*r, pz = _centroid.z + _dirV.z*r;
      const f = fieldAt(px, py, pz);
      if (prevField >= ISO && f < ISO) {
        // linear interp crossing
        const t = (prevField - ISO) / (prevField - f + 1e-9);
        rSurf = (r - (R_MAX-R_MIN)/STEPS) + t * ((R_MAX-R_MIN)/STEPS);
        break;
      }
      prevField = f;
      rSurf = r;
    }
    if (prevField >= ISO) rSurf = R_MAX * 0.5; // still inside -> clamp modest
    const px = _centroid.x + _dirV.x*rSurf;
    const py = _centroid.y + _dirV.y*rSurf;
    const pz = _centroid.z + _dirV.z*rSurf;
    envPosAttr.setXYZ(i, px, py, pz);
    // ESP value at surface point
    const e = espAt(px, py, pz);
    espColor(e, _tmpC);
    envColors.setXYZ(i, _tmpC.r, _tmpC.g, _tmpC.b);
  }
  envPosAttr.needsUpdate = true;
  envColors.needsUpdate = true;
  envGeo.computeVertexNormals();
  envGeo.computeBoundingSphere();
}

function fieldAt(px, py, pz) {
  let f = 0;
  for (const src of _srcs) {
    const dx = px - src.c.x, dy = py - src.c.y, dz = pz - src.c.z;
    f += src.s / (dx*dx + dy*dy + dz*dz + 0.05);
  }
  return f;
}
function espAt(px, py, pz) {
  let e = 0;
  for (const src of _srcs) {
    const dx = px - src.c.x, dy = py - src.c.y, dz = pz - src.c.z;
    e += src.q * src.s / (dx*dx + dy*dy + dz*dz + 0.08);
  }
  return e;
}

