function goToStep(targetT, duration = 1200) {
  if (tweenAnim) cancelAnimationFrame(tweenAnim);
  const startT = parseFloat(slider.value);
  const startTime = performance.now();
  function tick(now) {
    const p = Math.min(1, (now - startTime) / duration);
    const e = p < 0.5 ? 2*p*p : 1 - Math.pow(-2*p + 2, 2)/2;
    const cur = startT + (targetT - startT) * e;
    slider.value = cur;
    updateScene(cur);
    if (p < 1) tweenAnim = requestAnimationFrame(tick); else tweenAnim = null;
  }
  tweenAnim = requestAnimationFrame(tick);
}
