// @FIGURE_CODE_BEGIN
// === ELEMENT SPEC ===
// C atom         -> SphereGeometry(0.30) MeshStandardMaterial grey #808080
// Nu atom        -> SphereGeometry(0.34) MeshStandardMaterial dark red #b02a3a
// X atom         -> SphereGeometry(0.34) MeshStandardMaterial red-orange #c23b2e
// 3 substituents -> SphereGeometry(0.18) MeshStandardMaterial light grey #c8c8c8
// Nu-C bond      -> Line (dashed while forming, solid when formed)
// C-X bond       -> Line (solid while intact, dashed while breaking)
// 3 C-sub bonds  -> Line solid grey
// ESP envelope   -> merged per-atom lobe spheres, vertex-colored red->green->blue, translucent
// Labels         -> Nu, C, X, delta- via addLabel
// Scheme panel   -> HTML rows in #ui, active stage highlighted

const MAGENTA_CSS = '#d6219c';

// --- Lights ---
scene.add(new THREE.AmbientLight(0xffffff, 0.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.1);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.45);
fillLight.position.set(-3, 2, -3);
scene.add(fillLight);

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp01(v) { return Math.max(0, Math.min(1, v)); }

// --- ESP gradient: red (electron rich) -> yellow -> green -> blue (electron poor) ---
const _stopRed = new THREE.Color(0xd23b3b);
const _stopYel = new THREE.Color(0xe6cf4a);
const _stopGrn = new THREE.Color(0x74bd6a);
const _stopBlu = new THREE.Color(0x3f6fd0);
const _tmpC = new THREE.Color();
function espColor(v, out) {
  // v in [-1,1]; -1 red .. 0 green .. +1 blue
  if (v <= -0.5) out.lerpColors(_stopRed, _stopYel, clamp01((v + 1) / 0.5));
  else if (v <= 0) out.lerpColors(_stopYel, _stopGrn, clamp01((v + 0.5) / 0.5));
  else if (v <= 0.5) out.lerpColors(_stopGrn, _stopBlu, clamp01(v / 0.5));
  else out.copy(_stopBlu);
  return out;
}

// --- Atom meshes (fixed ball-and-stick palette) ---
const cMesh = new THREE.Mesh(new THREE.SphereGeometry(0.30, 32, 32),
  new THREE.MeshStandardMaterial({ color: 0x808080, roughness: 0.4, metalness: 0.1 }));
scene.add(cMesh);
const nuMesh = new THREE.Mesh(new THREE.SphereGeometry(0.34, 32, 32),
  new THREE.MeshStandardMaterial({ color: 0xb02a3a, roughness: 0.35, metalness: 0.05 }));
scene.add(nuMesh);
const xMesh = new THREE.Mesh(new THREE.SphereGeometry(0.34, 32, 32),
  new THREE.MeshStandardMaterial({ color: 0xc23b2e, roughness: 0.35, metalness: 0.05 }));
scene.add(xMesh);
const subMeshes = [];
for (let i = 0; i < 3; i++) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 24),
    new THREE.MeshStandardMaterial({ color: 0xc8c8c8, roughness: 0.5, metalness: 0.05 }));
  scene.add(m); subMeshes.push(m);
}

// --- Bonds ---
function makeBond() {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
  const mat = new THREE.LineDashedMaterial({ color: 0x555555, dashSize: 0.10, gapSize: 0.07, transparent: true, opacity: 1 });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  return { geo, mat, line };
}
const nuCBond = makeBond(), cXBond = makeBond();
const subBonds = [makeBond(), makeBond(), makeBond()];
subBonds.forEach(b => { b.mat.dashSize = 10; b.mat.gapSize = 0; }); // solid
function setBond(b, ax, ay, az, bx, by, bz) {
  const p = b.geo.attributes.position;
  p.setXYZ(0, ax, ay, az); p.setXYZ(1, bx, by, bz); p.needsUpdate = true;
  b.geo.computeBoundingSphere();
  if (b.line.computeLineDistances) b.line.computeLineDistances();
}

// --- ESP envelope: merged per-atom lobe spheres, vertex colored ---
const SEG = 22, VPS = (SEG + 1) * (SEG + 1), IPS = SEG * SEG * 6, NLOBE = 5;
const localDirs = new Float32Array(VPS * 3);
{
  let k = 0;
  for (let iy = 0; iy <= SEG; iy++) {
    const v = iy / SEG, theta = v * Math.PI;
    for (let ix = 0; ix <= SEG; ix++) {
      const u = ix / SEG, phi = u * Math.PI * 2;
      localDirs[k++] = Math.sin(theta) * Math.cos(phi);
      localDirs[k++] = Math.cos(theta);
      localDirs[k++] = Math.sin(theta) * Math.sin(phi);
    }
  }
}
const idxArr = new Uint16Array(NLOBE * IPS);
{
  let o = 0;
  for (let s = 0; s < NLOBE; s++) {
    const base = s * VPS;
    for (let iy = 0; iy < SEG; iy++) for (let ix = 0; ix < SEG; ix++) {
      const a = base + iy * (SEG + 1) + ix;
      const b = a + 1, c = a + (SEG + 1), dd = c + 1;
      idxArr[o++] = a; idxArr[o++] = c; idxArr[o++] = b;
      idxArr[o++] = b; idxArr[o++] = c; idxArr[o++] = dd;
    }
  }
}
const envPosArr = new Float32Array(NLOBE * VPS * 3);
const envColArr = new Float32Array(NLOBE * VPS * 3);
const envGeo = new THREE.BufferGeometry();
envGeo.setAttribute('position', new THREE.BufferAttribute(envPosArr, 3));
envGeo.setAttribute('color', new THREE.BufferAttribute(envColArr, 3));
envGeo.setIndex(new THREE.BufferAttribute(idxArr, 1));
const envMat = new THREE.MeshStandardMaterial({
  vertexColors: true, transparent: true, opacity: 0.42,
  roughness: 0.45, metalness: 0.0, side: THREE.DoubleSide, depthWrite: false
});
const envMesh = new THREE.Mesh(envGeo, envMat);
envMesh.renderOrder = 5;
scene.add(envMesh);

// state charges (drive ESP only)
let _qNu = -1, _qX = -0.3, _qC = 0.4;
const _lobe = [
  { p: nuMesh.position, r: 0.8 }, { p: xMesh.position, r: 0.8 },
  { p: cMesh.position, r: 0.62 }, { p: subMeshes[0].position, r: 0.40 },
  { p: subMeshes[1].position, r: 0.40 }
];
// re-point lobe 4 to sub[2] each frame (positions are live Vector3 refs; sub[2] handled below)
function espAt(px, py, pz) {
  let e = 0;
  const srcs = [
    [nuMesh.position, _qNu], [xMesh.position, _qX], [cMesh.position, _qC],
    [subMeshes[0].position, 0], [subMeshes[1].position, 0], [subMeshes[2].position, 0]
  ];
  for (const [c, q] of srcs) {
    const dx = px - c.x, dy = py - c.y, dz = pz - c.z;
    e += q / (dx * dx + dy * dy + dz * dz + 0.10);
  }
  return e;
}
function buildEnvelope(t) {
  _lobe[0].r = 0.78 + 0.45 * (1 - t);   // Nu swells when free
  _lobe[1].r = 0.78 + 0.45 * t;         // X swells when free
  _lobe[2].r = 0.62;
  _lobe[3].p = subMeshes[0].position; _lobe[4].p = subMeshes[1].position;
  const extra = subMeshes[2].position;
  const ESP_SCALE = 0.55;
  let vi = 0, ci = 0;
  for (let s = 0; s < NLOBE; s++) {
    const L = _lobe[s];
    for (let v = 0; v < VPS; v++) {
      const dx = localDirs[v * 3], dy = localDirs[v * 3 + 1], dz = localDirs[v * 3 + 2];
      const wx = L.p.x + dx * L.r, wy = L.p.y + dy * L.r, wz = L.p.z + dz * L.r;
      envPosArr[vi++] = wx; envPosArr[vi++] = wy; envPosArr[vi++] = wz;
      let val = espAt(wx, wy, wz) * ESP_SCALE;
      val = Math.max(-1, Math.min(1, val));
      espColor(val, _tmpC);
      envColArr[ci++] = _tmpC.r; envColArr[ci++] = _tmpC.g; envColArr[ci++] = _tmpC.b;
    }
  }
  // add sub[2] lobe by reusing lobe slot 4's color pass? Instead append via separate small mesh:
  envGeo.attributes.position.needsUpdate = true;
  envGeo.attributes.color.needsUpdate = true;
  envGeo.computeVertexNormals();
  envGeo.computeBoundingSphere();
  // sub[2] halo
  sub2Halo.position.copy(extra);
  const r2 = 0.40;
  const pa = sub2Halo.geometry.attributes.position;
  const ca = sub2Halo.geometry.attributes.color;
  for (let v = 0; v < VPS; v++) {
    const dx = localDirs[v * 3], dy = localDirs[v * 3 + 1], dz = localDirs[v * 3 + 2];
    const wx = extra.x + dx * r2, wy = extra.y + dy * r2, wz = extra.z + dz * r2;
    pa.setXYZ(v, dx * r2, dy * r2, dz * r2);
    let val = Math.max(-1, Math.min(1, espAt(wx, wy, wz) * ESP_SCALE));
    espColor(val, _tmpC); ca.setXYZ(v, _tmpC.r, _tmpC.g, _tmpC.b);
  }
  pa.needsUpdate = true; ca.needsUpdate = true;
  sub2Halo.geometry.computeVertexNormals();
  sub2Halo.geometry.computeBoundingSphere();
}
// separate small halo for 3rd substituent (keeps merged buffer at 5 lobes)
const sub2Geo = new THREE.BufferGeometry();
sub2Geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(VPS * 3), 3));
sub2Geo.setAttribute('color', new THREE.BufferAttribute(new Float32Array(VPS * 3), 3));
sub2Geo.setIndex(new THREE.BufferAttribute(idxArr.slice(0, IPS), 1));
const sub2Halo = new THREE.Mesh(sub2Geo, envMat);
sub2Halo.renderOrder = 5;
scene.add(sub2Halo);

// --- Labels ---
const lblNu = addLabel('Nu', new THREE.Vector3(), { color: MAGENTA_CSS, bold: true, fontSize: '15px' });
const lblC = addLabel('C', new THREE.Vector3(), { color: MAGENTA_CSS, bold: true, fontSize: '15px' });
const lblX = addLabel('X', new THREE.Vector3(), { color: MAGENTA_CSS, bold: true, fontSize: '15px' });
const lblDNu = addLabel('δ<sup>−</sup>', new THREE.Vector3(), { color: MAGENTA_CSS, fontSize: '13px' });
const lblDX = addLabel('δ<sup>−</sup>', new THREE.Vector3(), { color: MAGENTA_CSS, fontSize: '13px' });

// --- Interactivity ---
registerInteractive(nuMesh, {
  title: 'Nucleophile (Nu)',
  body: 'The nucleophile attacks from the backside (180° from the leaving group). It is electron-rich (red in the ESP envelope); its negative charge transfers to the leaving group as the reaction proceeds.',
  tooltip: 'Nucleophile — electron-rich (red ESP)'
});
registerInteractive(xMesh, {
  title: 'Leaving group (X)',
  body: 'The leaving group departs with the bonding electron pair. It becomes a free anion X⁻ in the products and is electron-rich (red ESP) at every stage.',
  tooltip: 'Leaving group — electron-rich (red ESP)'
});
registerInteractive(cMesh, {
  title: 'Electrophilic carbon (C)',
  body: 'The carbon is electron-poor (green/blue ESP) and undergoes Walden inversion: its three substituents flip like an umbrella through a planar transition state.',
  tooltip: 'Electrophilic carbon — electron-poor (green/blue ESP)'
});

// --- UI refs ---
const slider = document.getElementById('reactionProgress');
const captionEl = document.getElementById('stageCaption');
const fRows = [document.getElementById('fRow0'), document.getElementById('fRow1'), document.getElementById('fRow2')];
const btns = [document.getElementById('btnStep0'), document.getElementById('btnStep1'), document.getElementById('btnStep2')];
function highlightRow(idx) {
  fRows.forEach((r, i) => { if (!r) return; r.style.background = (i === idx) ? '#ffe3f3' : 'transparent'; r.style.fontWeight = (i === idx) ? 'bold' : 'normal'; });
  btns.forEach((b, i) => b.classList.toggle('active', i === idx));
}

// --- Update ---
function updateScene(t) {
  const nuX = lerp(-2.6, -1.05, t);
  const xX = lerp(1.05, 2.6, t);
  nuMesh.position.set(nuX, 0, 0);
  xMesh.position.set(xX, 0, 0);
  cMesh.position.set(0, 0, 0);

  // umbrella inversion of substituents
  const a = 0.42 * (2 * t - 1);
  const rr = Math.sqrt(Math.max(0, 1 - a * a));
  const bondLen = 1.0;
  for (let i = 0; i < 3; i++) {
    const ang = (i * 120 + 90) * Math.PI / 180;
    const px = a * bondLen, py = rr * bondLen * Math.cos(ang), pz = rr * bondLen * Math.sin(ang);
    subMeshes[i].position.set(px, py, pz);
    setBond(subBonds[i], 0, 0, 0, px, py, pz);
  }

  // Nu-C bond (forms)
  const nuCOrder = clamp01((t - 0.18) / 0.64);
  setBond(nuCBond, nuX, 0, 0, 0, 0, 0);
  nuCBond.line.visible = t > 0.06;
  if (nuCOrder < 0.9) { nuCBond.mat.dashSize = 0.10; nuCBond.mat.gapSize = 0.07; nuCBond.mat.opacity = 0.8; }
  else { nuCBond.mat.dashSize = 10; nuCBond.mat.gapSize = 0; nuCBond.mat.opacity = 1; }

  // C-X bond (breaks)
  const cXOrder = clamp01(1 - (t - 0.18) / 0.64);
  setBond(cXBond, 0, 0, 0, xX, 0, 0);
  cXBond.line.visible = t < 0.94;
  if (cXOrder < 0.9) { cXBond.mat.dashSize = 0.10; cXBond.mat.gapSize = 0.07; cXBond.mat.opacity = 0.8; }
  else { cXBond.mat.dashSize = 10; cXBond.mat.gapSize = 0; cXBond.mat.opacity = 1; }

  // ESP charges
  _qNu = lerp(-1.0, -0.12, t);
  _qX = lerp(-0.3, -1.0, t);
  _qC = lerp(0.4, 0.12, t);

  buildEnvelope(t);

  // labels track atoms
  lblNu.pos.set(nuX, 0.62, 0);
  lblX.pos.set(xX, 0.62, 0);
  lblC.pos.set(0, 0.55, 0);
  lblDNu.pos.set(nuX, 1.0, 0);
  lblDX.pos.set(xX, 1.0, 0);
  const showDelta = Math.abs(t - 0.5) < 0.30;
  lblDNu.div.style.display = showDelta ? '' : 'none';
  lblDX.div.style.display = showDelta ? '' : 'none';

  if (t < 0.33) { captionEl.textContent = 'Tetrahedral (reactants)'; highlightRow(0); }
  else if (t <= 0.67) { captionEl.textContent = 'Planar (transition state)'; highlightRow(1); }
  else { captionEl.textContent = 'Tetrahedral (products)'; highlightRow(2); }
}

slider.addEventListener('input', () => updateScene(parseFloat(slider.value)));

let tweenAnim = null;
function goToStep(targetT, duration = 1200) {
  if (tweenAnim) cancelAnimationFrame(tweenAnim);
  const startT = parseFloat(slider.value), startTime = performance.now();
  function tick(now) {
    const p = Math.min(1, (now - startTime) / duration);
    const e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
    const cur = startT + (targetT - startT) * e;
    slider.value = cur; updateScene(cur);
    if (p < 1) tweenAnim = requestAnimationFrame(tick); else tweenAnim = null;
  }
  tweenAnim = requestAnimationFrame(tick);
}
btns[0].addEventListener('click', () => goToStep(0));
btns[1].addEventListener('click', () => goToStep(0.5));
btns[2].addEventListener('click', () => goToStep(1));

